// n8n Code node: Build morning request
// Input: Morning context (coach_context('digest_morning')). Output: { body } for the Anthropic Messages API.
const ctx = $input.first().json || {};
if (!ctx.charter) return [{ json: { skip: true } }];
const { charter, ...facts } = ctx;
const now = DateTime.now().setZone('Europe/London');

const rules = `## How you are being used right now
This is the 10:00 morning digest in the user's Telegram fitness bot, sent automatically every day. He weighs first thing (today_so_far.weight_kg if it landed) and does not normally eat before 11:00. Write today's brief.

Blocks, in this order, one short block each. Skip a block only if there is nothing to say.
1. ⚖️ Weight: today's reading if logged, the 7-day average and direction vs last week (weight_trend), against the phase target in programme. Creatine water context while it applies (while a supplement change applies). No reading yet: one line saying so, ask for it.
2. 📈 Trend call: is the 7-day trend on plan for the phase? One line. Propose an adjustment only if the trend has been off for a week, per the charter.
3. 🔁 Yesterday: intake vs yesterday_plan.kcal_target, protein vs floor, training done or not (yesterday_sessions / yesterday.cardio_type), quiz answers if present (yesterday.energy, mood, soreness, hunger, substances, note), stool if present (yesterday_stool.types; comment only on a 1-2 or 6-7 with an obvious cause in yesterday_stool.prev_day_items, per the charter's Gut section). Facts, calmly. If today_plan.correction > 0, say today's budget is X lower to absorb yesterday's overshoot (the cap is already applied in code); plan, not punishment.
4. 🎯 Today: day type (today_plan.day_type) and how it was decided (source: logged, set by the user, or proposed with today_plan.reason), then the budget: kcal_target, protein_floor_g, carb_g, fat_g, fibre_floor_g. If proposed, one line: change it with "pull today", "rest day" etc.
5. 🍽️ Protein plan: four feeds of roughly 35-45g across the eating window (first meal about 11:00). On lifting days training is in programme.training_time, so say where the pre- or post-training feed lands and which meal carries the most. Rest and cardio days: spread evenly, dinner carries the meat.
6. 🏋️ Training: lifting day: which day, the template exercises for it (programme_days) in one line, focus lift named; a stalled lift from stalled gets the charter's one suggested change. Cardio day: which session (4x4 bike intervals or zone 2 swim/ride) given weekly_training this week. Rest: say rest.
7. ⚠️ Due: tape (last_tape; weekly waist/neck/hips, 4-weekly full set), creatine daily, open_pending items. Only what is actually due.

Rules:
- Layout per the charter's Tone and format section: one point per line, blank line between blocks, emoji marker at the start of each block's first line. Plain text, no markdown, no headings.
- Under 220 words. Numbers only from the facts. Never invent or estimate.
- British English, hyphens never em dashes.
- The digest is planning and adjustment; it is the one place an overshoot is addressed, and it is addressed calmly, once.`;

const user = `Morning digest for ${now.toFormat('cccc d MMMM yyyy')}, ${now.toFormat('HH:mm')} Europe/London.

Facts:
${JSON.stringify(facts)}`;

const body = {
  model: 'claude-sonnet-5-5',
  max_tokens: 4000,
  thinking: { type: 'adaptive' },
  output_config: { effort: 'medium' },
  system: [
    { type: 'text', text: charter, cache_control: { type: 'ephemeral' } },
    { type: 'text', text: rules },
  ],
  messages: [{ role: 'user', content: user }],
};
return [{ json: { body } }];

// n8n Code node: Morning text
const j = $input.first().json || {};
if (j.skip) return [];
const text = (j.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n').trim();
if (!text || j.error) return [{ json: { text: '⚠️ Morning digest failed to generate. Check Executions on n8n.' } }];
return [{ json: { text } }];

// n8n Code node: Build night quiz
// Input: Night context (coach_context('digest_night')). Deterministic: no model. Output: { text, keyboard, date }.
// Shared quiz renderer (duplicated in the night digest workflow and the bot's Quiz step node; keep in sync)
const QUIZ = {
  2: { key: 'energy',   q: '⚡ Energy today?\n1 flat, 3 normal, 5 full of beans', scale: true },
  3: { key: 'mood',     q: '🙂 Mood?\n1 low, 3 fine, 5 great', scale: true },
  4: { key: 'soreness', q: '💢 Soreness?\n1 none, 3 noticeable, 5 wrecked', scale: true },
  5: { key: 'hunger',   q: '🍽️ Hunger?\n1 not hungry, 3 normal, 5 ravenous', scale: true },
  6: { key: 'substances', q: '🍃 Anything today?', opts: [['None','none'],['Alcohol','alcohol'],['THC','thc'],['Both','both']] },
  7: { key: 'bowel_count', q: '🚽 Bowel movements today?', count: true },
  8: { key: 'stool',    q: '💩 Quality? Bristol scale\n1-2 hard, 3-4 ideal, 5 soft, 6-7 loose', stool: true },
  9: { key: 'note',     q: '📝 Anything to note?\nType "note: ..." or tap Skip', opts: [['⏭️ Skip','skip']] },
};
const LAST = 10;   // step 10 = done
const btn = (text, data) => ({ text, additionalFields: { callback_data: data } });
const kb = (rows) => ({ rows: rows.map(r => ({ row: { buttons: r } })) });
const answeredLine = (row) => {
  const parts = [];
  if (row.energy) parts.push(`⚡${row.energy}`);
  if (row.mood) parts.push(`🙂${row.mood}`);
  if (row.soreness) parts.push(`💢${row.soreness}`);
  if (row.hunger) parts.push(`🍽️${row.hunger}`);
  if (row.substances) parts.push(`🍃 ${row.substances}`);
  if (row.bowel_count != null) parts.push(`🚽${row.bowel_count === 4 ? '4+' : row.bowel_count}`);
  if (row.stool_quiz) parts.push(`💩${row.stool_quiz}`);
  return parts.join('  ');
};
// Returns { text, keyboard, layout } for a step given the daily row (answers so far) and the step-1 summary text
function renderStep(step, row, summary, variant) {
  if (step === 1) {
    if (variant === 'change') {
      return { text: `${summary}\n\n✏️ Send the fix as a normal message (food, weight, workout), then tap Continue.`, keyboard: kb([[btn('▶️ Continue', 'q:1:ok')]]), layout: 'continue' };
    }
    return { text: `${summary}\n\nIs this all correct?`, keyboard: kb([[btn('✅ Correct', 'q:1:ok'), btn('✏️ Change something', 'q:1:change')]]), layout: 'confirm' };
  }
  if (step >= 2 && step < LAST) {
    const s = QUIZ[step];
    const head = answeredLine(row);
    const text = (head ? head + '\n\n' : '') + s.q;
    let buttons, layout;
    if (s.scale) { buttons = [[1,2,3,4,5].map(n => btn(String(n), `q:${step}:${n}`))]; layout = 'scale'; }
    else if (s.count) { buttons = [[0,1,2,3].map(n => btn(String(n), `q:${step}:${n}`)).concat([btn('4+', `q:${step}:4`)])]; layout = 'count'; }
    else if (s.stool) { buttons = [[1,2,3,4].map(n => btn(String(n), `q:${step}:${n}`)), [5,6,7].map(n => btn(String(n), `q:${step}:${n}`)).concat([btn('⏭️ Skip', `q:${step}:skip`)])]; layout = 'stool'; }
    else { buttons = [s.opts.map(([t, v]) => btn(t, `q:${step}:${v}`))]; layout = step === 6 ? 'subs' : 'skip'; }
    return { text, keyboard: kb(buttons), layout };
  }
  // step LAST: done
  const head = answeredLine(row);
  const noteLine = row.note ? `\n📝 ${row.note}` : '';
  return { text: `${head}${noteLine}\n\n✅ All recorded. Night.`, keyboard: null, layout: 'final' };
}


const ctx = $input.first().json || {};
const t = ctx.today || {};
const log = ctx.today_log || [];
const sess = ctx.today_sessions || [];
const plan = ctx.today_plan || {};
const d = DateTime.now().setZone('Europe/London');
const lines = [`🌙 ${d.toFormat('ccc d MMM')}`];
lines.push(t.weight_kg ? `⚖️ ${Number(t.weight_kg).toFixed(1)}kg` : '⚖️ No weigh-in logged');
if (log.length || t.calories) {
  lines.push(`🍽️ ${Math.round(t.calories || 0)} kcal, ${Math.round(t.protein_g || 0)}g protein, ${log.length} item${log.length === 1 ? '' : 's'} (target ${plan.kcal_target} / ${plan.protein_floor_g})`);
} else {
  lines.push('🍽️ No food logged');
}
if (sess.length) lines.push(`🏋️ ${sess.map(s => `${s.type} session, ${s.sets} sets`).join('; ')}`);
else if (t.cardio_type) lines.push(`🚴 ${t.cardio_type}${t.cardio_mins ? ', ' + t.cardio_mins + ' min' : ''}`);
else lines.push(`🏋️ No training logged (${plan.day_type} day)`);
if (ctx.today_stool && ctx.today_stool.length) lines.push(`💩 ${ctx.today_stool.map(t => 'type ' + t).join(', ')}`);
if (ctx.open_pending && ctx.open_pending.length) lines.push(`❓ Still unresolved: ${ctx.open_pending.map(p => p.item).join(', ')}`);
const summary = lines.join('\n');
const r = renderStep(1, t, summary);
return [{ json: { text: r.text, keyboard: r.keyboard, date: d.toISODate() } }];
